terraform {
  backend "s3" {}
}
locals {
  version = module.service.version
  runners = {
    lambda = { image = "${aws_ecr_repository.r.repository_url}:${local.version}" }
    docker = { image = "amazonlinux:3" }
  }
}
resource "aws_ecr_repository" "r" {
  name = "runner"
}
resource "aws_codebuild_project" "runner" {
  for_each     = local.runners
  name         = each.key
  service_role = "arn:aws:iam::123456789012:role/codebuild"
  artifacts {
    type = "NO_ARTIFACTS"
  }
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = each.value.image
    type         = "ARM_CONTAINER"
  }
  source {
    type = "NO_SOURCE"
  }
}
resource "aws_cloudwatch_log_group" "runner" {
  for_each = local.runners
  name     = each.key
}

